CREATE TABLE IF NOT EXISTS users (id CHAR(36) PRIMARY KEY, name VARCHAR(255) NOT NULL, username VARCHAR(255) NOT NULL UNIQUE, password_hash TEXT NOT NULL, role ENUM('admin','cashier') NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS cashiers (id CHAR(36) PRIMARY KEY, user_id CHAR(36) UNIQUE, name VARCHAR(255) NOT NULL, employee_id VARCHAR(255) NOT NULL UNIQUE, email VARCHAR(255) NOT NULL, phone VARCHAR(50) NOT NULL, status ENUM('active','inactive') NOT NULL DEFAULT 'active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS academic_years (id CHAR(36) PRIMARY KEY, name VARCHAR(20) NOT NULL UNIQUE, active BOOLEAN NOT NULL DEFAULT FALSE, closed BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS app_settings (`key` VARCHAR(100) PRIMARY KEY, value JSON NOT NULL);
CREATE TABLE IF NOT EXISTS school_settings (id TINYINT PRIMARY KEY, school_name VARCHAR(255) NOT NULL DEFAULT 'Edify School', tagline TEXT NOT NULL, location TEXT NOT NULL, address TEXT NOT NULL, phone VARCHAR(50) NOT NULL, email VARCHAR(255) NOT NULL, website VARCHAR(255) NOT NULL, receipt_footer TEXT NOT NULL, principal VARCHAR(255) NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS school_classes (id CHAR(36) PRIMARY KEY, name VARCHAR(255) NOT NULL UNIQUE, sections JSON NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS fee_structures (id CHAR(36) PRIMARY KEY, name VARCHAR(255) NOT NULL, class_name VARCHAR(255) NOT NULL, academic_year_id CHAR(36) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY fee_structure_unique (name,class_name,academic_year_id), FOREIGN KEY (academic_year_id) REFERENCES academic_years(id));
CREATE TABLE IF NOT EXISTS fee_heads (id CHAR(36) PRIMARY KEY, structure_id CHAR(36) NOT NULL, name VARCHAR(255) NOT NULL, amount DECIMAL(12,2) NOT NULL, position INT NOT NULL DEFAULT 0, FOREIGN KEY (structure_id) REFERENCES fee_structures(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS fee_terms (id CHAR(36) PRIMARY KEY, structure_id CHAR(36) NOT NULL, name VARCHAR(255) NOT NULL, amount DECIMAL(12,2) NOT NULL, due_date DATE NOT NULL, position INT NOT NULL DEFAULT 0, FOREIGN KEY (structure_id) REFERENCES fee_structures(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS students (id CHAR(36) PRIMARY KEY, admission_no VARCHAR(255) NOT NULL UNIQUE, student_id VARCHAR(255) NOT NULL UNIQUE, first_name VARCHAR(255) NOT NULL, last_name VARCHAR(255) NOT NULL DEFAULT '', dob DATE NOT NULL, gender ENUM('Male','Female','Other') NOT NULL, blood_group VARCHAR(50) NOT NULL DEFAULT '', aadhaar VARCHAR(50) NOT NULL DEFAULT '', admission_date DATE NOT NULL, father_name VARCHAR(255) NOT NULL DEFAULT '', father_phone VARCHAR(50) NOT NULL DEFAULT '', father_email VARCHAR(255) NOT NULL DEFAULT '', mother_name VARCHAR(255) NOT NULL DEFAULT '', mother_phone VARCHAR(50) NOT NULL DEFAULT '', mother_email VARCHAR(255) NOT NULL DEFAULT '', guardian_name VARCHAR(255) NOT NULL DEFAULT '', guardian_relation VARCHAR(100) NOT NULL DEFAULT '', guardian_phone VARCHAR(50) NOT NULL DEFAULT '', address TEXT NOT NULL, previous_school VARCHAR(255) NOT NULL DEFAULT '', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS student_enrollments (id CHAR(36) PRIMARY KEY, student_id CHAR(36) NOT NULL, academic_year_id CHAR(36) NOT NULL, class_name VARCHAR(255) NOT NULL, section VARCHAR(50) NOT NULL DEFAULT '', roll_no VARCHAR(50) NOT NULL DEFAULT '', previous_class VARCHAR(255) NOT NULL DEFAULT '', fee_category VARCHAR(100) NOT NULL DEFAULT 'Regular', structure_id CHAR(36), discount DECIMAL(12,2) NOT NULL DEFAULT 0, archived_at TIMESTAMP NULL, archived_by CHAR(36), archive_reason TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY enrollment_unique (student_id,academic_year_id), FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE, FOREIGN KEY (academic_year_id) REFERENCES academic_years(id), FOREIGN KEY (structure_id) REFERENCES fee_structures(id) ON DELETE SET NULL, FOREIGN KEY (archived_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS payments (id CHAR(36) PRIMARY KEY, receipt_no VARCHAR(100) NOT NULL UNIQUE, student_id CHAR(36), enrollment_id CHAR(36), student_admission_no VARCHAR(255) NOT NULL, student_name VARCHAR(255) NOT NULL, payment_date DATE NOT NULL, amount DECIMAL(12,2) NOT NULL, mode ENUM('Cash','UPI','Card','Bank Transfer') NOT NULL, reference VARCHAR(255) NOT NULL DEFAULT '', remarks TEXT NOT NULL, cashier_name VARCHAR(255) NOT NULL, academic_year_id CHAR(36) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'Success', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE SET NULL, FOREIGN KEY (enrollment_id) REFERENCES student_enrollments(id) ON DELETE SET NULL, FOREIGN KEY (academic_year_id) REFERENCES academic_years(id));
